# worker/tasks.py - Celery background job worker for report generation
import os
import subprocess
import tempfile
from celery import Celery
from celery.signals import worker_init

app = Celery('tasks', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))

app.conf.update(
    task_serializer='pickle',
    accept_content=['pickle', 'json'],
    result_serializer='pickle',
    task_always_eager=False,
    worker_prefetch_multiplier=1,
)


class ReportConfig:
    """Configuration object for report generation - supports pickle for complex configs"""
    def __init__(self, template_name, output_format, filters=None):
        self.template_name = template_name
        self.output_format = output_format
        self.filters = filters or {}

    def __reduce__(self):
        return (self.__class__, (self.template_name, self.output_format, self.filters))


@app.task(name='worker.tasks.generate_report')
def generate_report(config):
    """Generate a report based on the provided configuration object.
    Config can be a dict or a ReportConfig instance (via pickle)."""
    if isinstance(config, ReportConfig):
        template = config.template_name
        fmt = config.output_format
        filters = config.filters
    elif isinstance(config, dict):
        template = config.get('template_name', 'default')
        fmt = config.get('output_format', 'pdf')
        filters = config.get('filters', {})
    else:
        raise ValueError(f"Unsupported config type: {type(config)}")

    # Generate report using system tool
    report_path = f"/tmp/reports/{template}_{fmt}.out"
    os.makedirs(os.path.dirname(report_path), exist_ok=True)

    cmd = ['report-gen', '--template', template, '--format', fmt, '--output', report_path]
    for key, value in filters.items():
        cmd.extend([f'--filter-{key}', str(value)])

    result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)

    if result.returncode != 0:
        raise RuntimeError(f"Report generation failed: {result.stderr}")

    return {'status': 'complete', 'path': report_path}


@app.task(name='worker.tasks.cleanup_old_reports')
def cleanup_old_reports(max_age_hours=24):
    """Remove reports older than max_age_hours from temp storage."""
    import time
    report_dir = '/tmp/reports'
    if not os.path.exists(report_dir):
        return {'cleaned': 0}

    cleaned = 0
    now = time.time()
    for fname in os.listdir(report_dir):
        fpath = os.path.join(report_dir, fname)
        if os.stat(fpath).st_mtime < now - (max_age_hours * 3600):
            os.unlink(fpath)
            cleaned += 1
    return {'cleaned': cleaned}


@app.task(name='worker.tasks.install_plugin')
def install_plugin(plugin_name, plugin_url):
    """Install a report plugin from internal registry.
    Writes plugin to /opt/plugins/ for subsequent use."""
    plugin_dir = '/opt/plugins'
    os.makedirs(plugin_dir, exist_ok=True)

    # Download and install plugin
    import urllib.request
    plugin_path = os.path.join(plugin_dir, f"{plugin_name}.py")
    urllib.request.urlretrieve(plugin_url, plugin_path)

    # Verify plugin loads correctly
    import importlib.util
    spec = importlib.util.spec_from_file_location(plugin_name, plugin_path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)

    return {'status': 'installed', 'plugin': plugin_name, 'path': plugin_path}


@worker_init.connect
def configure_worker(sender=None, **kwargs):
    """Worker initialization - set up environment."""
    os.environ.setdefault('REPORT_CACHE_DIR', '/tmp/cache')
    os.makedirs('/tmp/cache', exist_ok=True)
    print(f"Worker initialized. PID={os.getpid()}, UID={os.getuid()}")
